function dmSplitTags(record){
  var out={}, order=[], parts=String(record||'').split(';');
  for(var i=0;i<parts.length;i++){
    var p=parts[i].trim();
    if(!p) continue;
    var eq=p.indexOf('=');
    if(eq<0){ continue; }
    var k=p.slice(0,eq).trim().toLowerCase(), v=p.slice(eq+1).trim();
    if(out[k]===undefined){ out[k]=v; order.push(k); }
  }
  return { tags:out, order:order };
}
function dmParse(record){
  var raw=String(record||'').trim().replace(/^"|"$/g,'');
  if(!raw) return { error:'请输入 DMARC 记录' };
  var r=dmSplitTags(raw), t=r.tags;
  if(!t.v) return { error:'缺少 v 标签，DMARC 记录必须以 v=DMARC1 开头' };
  if(t.v.toUpperCase()!=='DMARC1') return { error:'v 标签必须为 DMARC1，当前为 '+t.v };
  if(r.order[0]!=='v') return { error:'v 必须是第一个标签' };
  return { error:null, tags:t, order:r.order, raw:raw };
}
function dmPolicyScore(t){
  var p=(t.p||'none').toLowerCase(), sp=(t.sp||p).toLowerCase();
  var pct=t.pct===undefined ? 100 : parseInt(t.pct,10);
  if(isNaN(pct)) pct=100;
  var base = p==='reject' ? 60 : p==='quarantine' ? 40 : 10;
  var sub  = sp==='reject' ? 15 : sp==='quarantine' ? 10 : 2;
  var cov  = Math.round(pct/100*15);
  var rep  = (t.rua?7:0) + (t.ruf?3:0);
  return Math.max(0, Math.min(100, base+sub+cov+rep));
}
function dmGrade(score){
  if(score>=90) return 'A';
  if(score>=75) return 'B';
  if(score>=60) return 'C';
  if(score>=40) return 'D';
  return 'F';
}
function dmMailtos(v){
  if(!v) return [];
  return String(v).split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s; });
}
function dmLint(parsed){
  if(!parsed || parsed.error) return [];
  var t=parsed.tags, out=[];
  var p=(t.p||'').toLowerCase();
  if(!t.p) out.push({ level:'错误', msg:'缺少必填的 p 标签（none / quarantine / reject）' });
  else if(['none','quarantine','reject'].indexOf(p)<0) out.push({ level:'错误', msg:'p 取值非法：'+t.p });
  else if(p==='none') out.push({ level:'建议', msg:'p=none 仅监控不拦截，建议逐步升级到 quarantine 再到 reject' });
  if(t.pct!==undefined){
    var pct=parseInt(t.pct,10);
    if(isNaN(pct)||pct<0||pct>100) out.push({ level:'错误', msg:'pct 必须是 0-100 的整数' });
    else if(pct<100) out.push({ level:'建议', msg:'pct='+pct+' 表示只对部分邮件应用策略，全量防护应设为 100' });
  }
  if(!t.rua) out.push({ level:'建议', msg:'未配置 rua，收不到聚合报告将难以观测认证失败情况' });
  var rua=dmMailtos(t.rua);
  for(var i=0;i<rua.length;i++) if(rua[i].indexOf('mailto:')!==0) out.push({ level:'错误', msg:'rua 地址必须以 mailto: 开头：'+rua[i] });
  var ruf=dmMailtos(t.ruf);
  for(var j=0;j<ruf.length;j++) if(ruf[j].indexOf('mailto:')!==0) out.push({ level:'错误', msg:'ruf 地址必须以 mailto: 开头：'+ruf[j] });
  if(t.adkim!==undefined && ['r','s'].indexOf(String(t.adkim).toLowerCase())<0) out.push({ level:'错误', msg:'adkim 只能是 r 或 s' });
  if(t.aspf!==undefined && ['r','s'].indexOf(String(t.aspf).toLowerCase())<0) out.push({ level:'错误', msg:'aspf 只能是 r 或 s' });
  if(t.fo!==undefined && !/^[01ds](:[01ds])*$/.test(String(t.fo))) out.push({ level:'错误', msg:'fo 取值应为 0/1/d/s 的冒号组合' });
  if(t.ri!==undefined && !(parseInt(t.ri,10)>0)) out.push({ level:'错误', msg:'ri 必须是正整数秒数' });
  var known=['v','p','sp','pct','rua','ruf','adkim','aspf','fo','ri','rf'];
  for(var k=0;k<parsed.order.length;k++)
    if(known.indexOf(parsed.order[k])<0) out.push({ level:'建议', msg:'未知标签：'+parsed.order[k] });
  return out;
}
function dmExplain(parsed){
  if(!parsed || parsed.error) return [];
  var t=parsed.tags, out=[];
  var pmap={ none:'仅监控，不做任何拦截', quarantine:'认证失败的邮件进入垃圾箱', reject:'认证失败的邮件直接拒收' };
  out.push(['p 主策略', pmap[(t.p||'none').toLowerCase()] || t.p]);
  out.push(['sp 子域策略', t.sp ? (pmap[String(t.sp).toLowerCase()]||t.sp) : '未设置，继承主策略']);
  out.push(['pct 应用比例', (t.pct===undefined?'100':t.pct)+'% 的邮件应用该策略']);
  out.push(['adkim DKIM 对齐', String(t.adkim||'r').toLowerCase()==='s' ? '严格：域名必须完全一致' : '宽松：允许子域']);
  out.push(['aspf SPF 对齐', String(t.aspf||'r').toLowerCase()==='s' ? '严格：域名必须完全一致' : '宽松：允许子域']);
  out.push(['rua 聚合报告', dmMailtos(t.rua).length ? dmMailtos(t.rua).join(', ') : '未配置']);
  out.push(['ruf 取证报告', dmMailtos(t.ruf).length ? dmMailtos(t.ruf).join(', ') : '未配置']);
  out.push(['ri 报告周期', (t.ri ? t.ri : '86400')+' 秒']);
  return out;
}
function dmBuild(opt){
  opt = opt || {};
  var parts=['v=DMARC1', 'p='+(opt.p||'none')];
  if(opt.sp) parts.push('sp='+opt.sp);
  if(opt.rua) parts.push('rua=mailto:'+opt.rua);
  if(opt.ruf) parts.push('ruf=mailto:'+opt.ruf);
  if(opt.pct!==undefined && opt.pct!=='' && String(opt.pct)!=='100') parts.push('pct='+opt.pct);
  if(opt.adkim) parts.push('adkim='+opt.adkim);
  if(opt.aspf) parts.push('aspf='+opt.aspf);
  return parts.join('; ') + ';';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dmSplitTags:dmSplitTags, dmParse:dmParse, dmPolicyScore:dmPolicyScore,
    dmGrade:dmGrade, dmMailtos:dmMailtos, dmLint:dmLint, dmExplain:dmExplain, dmBuild:dmBuild };
}
if (typeof window !== 'undefined') {
  window.DmarcForgePure = { dmSplitTags:dmSplitTags, dmParse:dmParse, dmPolicyScore:dmPolicyScore,
    dmGrade:dmGrade, dmMailtos:dmMailtos, dmLint:dmLint, dmExplain:dmExplain, dmBuild:dmBuild };
}
